import re

def parse_mtr(report: str):
    # Expects lines like: " 2. isp-gateway  5.2%  120  18.4  22.1"
    hops = []
    for line in report.splitlines():
        m = re.match(r"\s*(\d+)\.\s+\S+\s+([\d.]+)%\s+\d+\s+([\d.]+)\s+([\d.]+)", line)
        if m:
            hops.append({
                "hop": int(m.group(1)),
                "loss": float(m.group(2)),
                "avg_ms": float(m.group(3)),
                "worst_ms": float(m.group(4)),
            })
    return hops

def find_boundary(hops, loss_thresh=5.0, jump_thresh=25.0):
    # WHY: hop 1 is your LAN. Blame the ISP only when
    # degradation *starts* at hop 2+ and persists downstream.
    for i in range(1, len(hops)):
        prev, cur = hops[i-1], hops[i]
        jump = cur["avg_ms"] - prev["avg_ms"]
        if cur["loss"] >= loss_thresh or jump >= jump_thresh:
            owner = "home LAN" if cur["hop"] == 1 else "ISP / upstream"
            return cur["hop"], owner, jump
    return None, "healthy", 0.0

# Example: hop 2 jumps +40ms with 8% loss -> ISP-side, not app-side.
